#include <WiFi.h>
const char* ssid = "YOUR_WIFI_NAME";
const char* password = "YOUR_WIFI_PASSWORD";
void setup() {
    Serial.begin(115200);
    WiFi.mode(WIFI_STA);
    WiFi.begin(ssid, password);
}
void loop() {
    if (WiFi.status() == WL_CONNECTED) Serial.println(WiFi.localIP());
    else Serial.println("waiting for Wi-Fi");
    delay(2000);
}

